def validate_structure() -> None:
    """Validate the embedded source tree before installation."""

    expected = set(FILES)
    actual = {path for path in FILES}
    if expected != actual:
        raise RuntimeError("Embedded source structure validation failed.")


def validate_style() -> None:
    """Validate Python syntax and required module/class/function docstrings."""

    for relative_path, source in FILES.items():
        if not relative_path.endswith(".py"):
            continue

        tree = ast.parse(source, filename=relative_path)
        if ast.get_docstring(tree) is None:
            raise RuntimeError(f"Module docstring missing: {relative_path}")

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                if ast.get_docstring(node) is None:
                    raise RuntimeError(
                        f"Definition docstring missing: {relative_path}:{node.name}",
                    )


def validate_manifest() -> None:
    """Validate the embedded installer manifest."""

    manifest = json.loads(FILES[".installer_manifest.json"])
    if manifest["module"] != "patient_emergency":
        raise RuntimeError("Invalid module manifest.")
    if manifest["canonical_patient"] != (
        "apps.patient_management.patients.models.Patient"
    ):
        raise RuntimeError("Canonical Patient reference is invalid.")


def validate_architecture() -> None:
    """Validate the required architectural layers."""

    required = (
        "models/emergency.py",
        "selectors/emergency.py",
        "services/emergency.py",
        "policies/emergency.py",
        "permissions/emergency.py",
        "workflow_registry.py",
        "workflows/creation.py",
        "workflows/update.py",
        "workflows/deletion.py",
        "workflows/lifecycle.py",
        "events/created.py",
        "events/updated.py",
        "events/deleted.py",
        "events/status_changed.py",
        "api/serializers/create.py",
        "api/serializers/detail.py",
        "api/serializers/list.py",
        "api/serializers/update.py",
    )

    missing = [path for path in required if path not in FILES]
    if missing:
        raise RuntimeError(f"Architecture files missing: {missing}")


def validate_compile() -> None:
    """Compile every embedded Python source file."""

    temp_root = TARGET.parent / ".emergency_installer_compile"
    if temp_root.exists():
        shutil.rmtree(temp_root)

    temp_root.mkdir(parents=True)
    try:
        for relative_path, source in FILES.items():
            if not relative_path.endswith(".py"):
                continue

            destination = temp_root / relative_path
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(source, encoding="utf-8")

        result = subprocess.run(
            [
                sys.executable,
                "-m",
                "compileall",
                "-q",
                str(temp_root),
            ],
            capture_output=True,
            text=True,
        )
        if result.returncode != 0:
            raise RuntimeError(result.stderr or result.stdout)
    finally:
        shutil.rmtree(temp_root, ignore_errors=True)


def write_source() -> None:
    """Write the validated source tree to the target directory."""

    TARGET.mkdir(parents=True, exist_ok=True)

    for relative_path, source in FILES.items():
        destination = TARGET / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        if relative_path.endswith(".json"):
            destination.write_text(source, encoding="utf-8")
        else:
            destination.write_text(source, encoding="utf-8")


def verify_installation() -> None:
    """Verify that every expected source file exists after installation."""

    for relative_path in FILES:
        destination = TARGET / relative_path
        if not destination.is_file():
            raise RuntimeError(
                f"Installation verification failed: {relative_path}",
            )


def main() -> None:
    """Run the fresh Patient Emergency installation."""

    print("DatavionOS Patient Emergency Fresh Installer v1.0.0")
    print(f"Target: {TARGET}")

    validate_structure()
    print("STRUCTURE: PASS")

    validate_manifest()
    print("MANIFEST: PASS")

    validate_style()
    python_files = sum(1 for path in FILES if path.endswith(".py"))
    print(f"STYLE: PASS ({python_files} Python files)")

    validate_architecture()
    print("ARCHITECTURE: PASS")

    validate_compile()
    print(f"PY_COMPILE: PASS ({python_files} files)")

    if TARGET.exists():
        shutil.rmtree(TARGET)
        print("OLD EMERGENCY DIRECTORY: DELETED")

    write_source()
    print("FRESH EMERGENCY DIRECTORY: CREATED")

    verify_installation()
    print("VERIFY: PASS")
    print("INSTALLATION COMPLETE")
    print(
        "Workflow chain: API -> RBAC -> Workflow -> Policy -> "
        "Service -> Model -> Domain Event",
    )
    print(
        "Canonical Patient: apps.patient_management.patients.models.Patient",
    )
    print("No migration generated.")
    print("No backup generated.")
    print("No __pycache__ generated by installer.")


if __name__ == "__main__":
    main()
